quiz.prompt:
Şifre penceresi 3000 ms ve şifre 3 basış. Basışlar t = 0, 1500, 3200, 3500 ve 4000 ms'de geliyor ve her biri için tamam() çağrılıyor. Çıktı ne olur?

```
const unsigned long PENCERE = 3000;
int basis = 0;
unsigned long ilk = 0;

bool tamam(unsigned long t) {
  if (basis == 0 || t - ilk > PENCERE) {
    basis = 1;
    ilk = t;
  } else {
    basis++;
  }
  return basis >= 3;
}

void setup() {
  Serial.begin(9600);
  unsigned long zamanlar[] = {0, 1500, 3200, 3500, 4000};
  for (int i = 0; i < 5; i++) {
    Serial.print(tamam(zamanlar[i]) ? "E " : "H ");
  }
  Serial.println();
}

void loop() {}
```

